/* @lc app=leetcode id=1937 lang=kotlin */ class Solution { fun maxPoints(points: Array<IntArray>): Long = points.drop(1).fold(points[0].map { it.toLong() }) { prev, row -> LongArray(row.size).let { l -> row.indices.forEach { j -> l[j] = if (j == 0) prev[0] else maxOf(l[j - 1] - 1, prev[j]) }.let { LongArray(row.size).let { r -> (row.size - 1 downTo 0).forEach { j -> r[j] = if (j == row.size - 1) prev[j] else maxOf(r[j + 1] - 1, prev[j]) }.let { row.indices.map { j -> row[j] + maxOf(l[j], r[j]) } } } } } }.max() }